:ON ERROR EXIT
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @Source uniqueidentifier=NEWID(),@Outgoing uniqueidentifier=NEWID(),@Incoming uniqueidentifier=NEWID(),@Course uniqueidentifier=NEWID(),@Session uniqueidentifier=NEWID(),@Assignment uniqueidentifier=NEWID(),@OtherSession uniqueidentifier=NEWID();
INSERT staging.ImportBatch(ImportBatchId,StartedAtUtc,Status,SourceManifestSha256,ImporterVersion,ValidationSummaryJson) VALUES(@Source,SYSUTCDATETIME(),N'synthetic',REPLICATE('E',64),N'test',N'{}');
INSERT paws.Faculty(FacultyId,RecordType,DisplayName,Active,SourceImportBatchId) VALUES(@Outgoing,N'faculty',N'Synthetic ADFA Outgoing',1,@Source),(@Incoming,N'faculty',N'Synthetic ADFA Incoming',1,@Source);
INSERT paws.SwapCandidate(FacultyId) VALUES(@Outgoing),(@Incoming);
INSERT paws.UserProfile(FirebaseUid,Email,DisplayName,BaseRole,FacultyId,Active,MustChangePassword) VALUES(N'adfa-preview-admin',N'preview-admin@example.test',N'Synthetic ADFA',N'adfa_regular',NULL,1,0),(N'adfa-preview-faculty',N'preview-faculty@example.test',N'Synthetic Faculty',N'faculty',@Outgoing,1,0);
INSERT paws.Course(CourseId,CourseCode,CourseName,SourceImportBatchId) VALUES(@Course,N'ADFA_TEST',N'Synthetic preview course',@Source);
INSERT paws.Session(SessionId,AcademicYear,CurriculumYear,CourseId,CourseCode,CourseName,Topic,SessionType,SessionDate,StartTime,EndTime,SourceImportBatchId) VALUES(@Session,N'2026-27',N'2',@Course,N'ADFA_TEST',N'Synthetic preview course',N'Synthetic topic',N'LEC','2026-11-05','09:00','10:00',@Source);
INSERT paws.SessionAssignment(SessionAssignmentId,SessionId,FacultyId,SourceFacultyName,FacultyResolutionStatus,TeachingRole,DoeCredit,SourceImportBatchId,SourceRow) VALUES(@Assignment,@Session,@Outgoing,N'Synthetic ADFA Outgoing',N'resolved',N'Lab Lead',0.42,@Source,1);
DECLARE @Candidate uniqueidentifier=(SELECT CandidateKey FROM paws.SwapCandidate WHERE FacultyId=@Incoming),@Snapshot varchar(64)=CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),paws_api.SessionSwapSnapshot(@Session))),2),@BadSnapshot varchar(64)=REPLICATE('0',64),@Rejected bit=0;
DECLARE @Reply TABLE(responseJson nvarchar(max));
INSERT @Reply EXEC paws_api.GetAdfaSwapFacultyPreview N'adfa-preview-admin',@Session,@Assignment,@Candidate,@Snapshot;
DECLARE @Json nvarchar(max)=(SELECT responseJson FROM @Reply);
IF JSON_VALUE(@Json,'$.availabilityStatus')<>N'Available' OR TRY_CONVERT(decimal(12,6),JSON_VALUE(@Json,'$.persistedDoeCredit'))<>0.42 OR JSON_VALUE(@Json,'$.teachingRole')<>N'Lab Lead' OR TRY_CONVERT(uniqueidentifier,JSON_VALUE(@Json,'$.outgoingFacultyId'))<>@Outgoing OR TRY_CONVERT(uniqueidentifier,JSON_VALUE(@Json,'$.incomingFacultyId'))<>@Incoming THROW 53990,'Preview did not bind the exact assignment and active candidate.',1;
BEGIN TRY EXEC paws_api.GetAdfaSwapFacultyPreview N'adfa-preview-faculty',@Session,@Assignment,@Candidate,@Snapshot;END TRY BEGIN CATCH IF ERROR_NUMBER()=53003 SET @Rejected=1;ELSE THROW;END CATCH;
IF @Rejected=0 THROW 53990,'Faculty could read private ADFA preview context.',1;
SET @Rejected=0;BEGIN TRY EXEC paws_api.GetAdfaSwapFacultyPreview N'adfa-preview-admin',@Session,@Assignment,@Candidate,@BadSnapshot;END TRY BEGIN CATCH IF ERROR_NUMBER()=53010 SET @Rejected=1;ELSE THROW;END CATCH;
IF @Rejected=0 THROW 53990,'Stale session preview was accepted.',1;
UPDATE paws.Faculty SET Active=0 WHERE FacultyId=@Incoming;
SET @Rejected=0;BEGIN TRY EXEC paws_api.GetAdfaSwapFacultyPreview N'adfa-preview-admin',@Session,@Assignment,@Candidate,@Snapshot;END TRY BEGIN CATCH IF ERROR_NUMBER()=53004 SET @Rejected=1;ELSE THROW;END CATCH;
IF @Rejected=0 THROW 53990,'Inactive candidate was accepted.',1;
UPDATE paws.Faculty SET Active=1 WHERE FacultyId=@Incoming;
DECLARE @Afc uniqueidentifier=NEWID(),@AfcRequest uniqueidentifier=NEWID();
EXEC paws_api.CreateAfcRecord @Afc,@Incoming,'2026-11-05','2026-11-05',N'vacation',N'PRIVATE AFC DETAIL',N'adfa-preview-admin',N'Synthetic ADFA',@AfcRequest;
DELETE @Reply;INSERT @Reply EXEC paws_api.GetAdfaSwapFacultyPreview N'adfa-preview-admin',@Session,@Assignment,@Candidate,@Snapshot;
SELECT @Json=responseJson FROM @Reply;
IF JSON_VALUE(@Json,'$.availabilityStatus')<>N'Unavailable' OR @Json LIKE N'%PRIVATE AFC DETAIL%' OR @Json LIKE N'%vacation%' THROW 53990,'AFC availability was missed or disclosed private absence details.',1;
DECLARE @Activity uniqueidentifier=NEWID();
INSERT paws.CalendarActivity(ActivityId,FacultyId,Category,OriginalLabel,StartDate,EndDate,ImportBatchId,ImportRowId,SourceSha256,SourceSheet,SourceRow,CreatedByUid)
SELECT TOP(1) @Activity,@Incoming,N'ccc',N'PRIVATE WORK DETAIL','2026-11-05','2026-11-05',ImportBatchId,ImportRowId,SourceSha256,N'synthetic-adfa-preview',991,N'adfa-preview-admin' FROM paws.CalendarActivity;
IF @@ROWCOUNT<>1 THROW 53990,'Synthetic Calendar prerequisite is missing.',1;
DELETE @Reply;INSERT @Reply EXEC paws_api.GetAdfaSwapFacultyPreview N'adfa-preview-admin',@Session,@Assignment,@Candidate,@Snapshot;
SELECT @Json=responseJson FROM @Reply;
IF JSON_VALUE(@Json,'$.availabilityStatus')<>N'Needs Review' OR @Json LIKE N'%PRIVATE WORK DETAIL%' THROW 53990,'Unknown working time was hidden by known AFC or private work details leaked.',1;
DELETE paws.CalendarActivity WHERE ActivityId=@Activity;
DECLARE @AfcVersion varchar(16)=(SELECT CONVERT(varchar(16),CONVERT(binary(8),AfcVersion),2) FROM paws.AfcManualRecord WHERE AfcRecordId=@Afc),@CancelKey uniqueidentifier=NEWID();
EXEC paws_api.CancelAfcRecord @Afc,N'manual',@AfcVersion,N'adfa-preview-admin',N'Synthetic ADFA',@CancelKey;
INSERT paws.Session(SessionId,AcademicYear,CurriculumYear,CourseId,CourseCode,CourseName,Topic,SessionType,SessionDate,StartTime,EndTime,SourceImportBatchId) VALUES(@OtherSession,N'2026-27',N'2',@Course,N'ADFA_TEST',N'Synthetic preview course',N'Public conflict topic',N'LEC','2026-11-05','09:30','10:30',@Source);
INSERT paws.SessionAssignment(SessionAssignmentId,SessionId,FacultyId,SourceFacultyName,FacultyResolutionStatus,TeachingRole,SourceImportBatchId,SourceRow) VALUES(NEWID(),@OtherSession,@Incoming,N'Synthetic ADFA Incoming',N'resolved',N'Primary',@Source,2);
DELETE @Reply;INSERT @Reply EXEC paws_api.GetAdfaSwapFacultyPreview N'adfa-preview-admin',@Session,@Assignment,@Candidate,@Snapshot;
SELECT @Json=responseJson FROM @Reply;
IF JSON_VALUE(@Json,'$.availabilityStatus')<>N'Unavailable' OR JSON_VALUE(@Json,'$.conflicts[0].courseCode')<>N'ADFA_TEST' THROW 53990,'Live timetable conflict is missing.',1;
UPDATE paws.Session SET StartTime='10:00',EndTime='11:00' WHERE SessionId=@OtherSession;
DELETE @Reply;INSERT @Reply EXEC paws_api.GetAdfaSwapFacultyPreview N'adfa-preview-admin',@Session,@Assignment,@Candidate,@Snapshot;
IF JSON_VALUE((SELECT responseJson FROM @Reply),'$.availabilityStatus')<>N'Available' THROW 53990,'Adjacent teaching interval became an overlap.',1;
UPDATE paws.Session SET StartTime=NULL WHERE SessionId=@OtherSession;
DELETE @Reply;INSERT @Reply EXEC paws_api.GetAdfaSwapFacultyPreview N'adfa-preview-admin',@Session,@Assignment,@Candidate,@Snapshot;
IF JSON_VALUE((SELECT responseJson FROM @Reply),'$.availabilityStatus')<>N'Needs Review' THROW 53990,'Missing timetable time was treated as confirmed availability.',1;
CREATE USER adfa_preview_runtime WITHOUT LOGIN;
ALTER ROLE paws_runtime_swap_read ADD MEMBER adfa_preview_runtime;
EXECUTE AS USER=N'adfa_preview_runtime';
EXEC paws_api.GetAdfaSwapFacultyPreview N'adfa-preview-admin',@Session,@Assignment,@Candidate,@Snapshot;
SET @Rejected=0;BEGIN TRY SELECT * FROM paws.SwapCandidate;END TRY BEGIN CATCH IF ERROR_NUMBER()=229 SET @Rejected=1;ELSE THROW;END CATCH;
REVERT;
IF @Rejected=0 THROW 53990,'Preview role received direct candidate mapping access.',1;
ALTER ROLE paws_runtime_swap_read DROP MEMBER adfa_preview_runtime;
DROP USER adfa_preview_runtime;
PRINT 'ADFA_SWAP_PREVIEW_SQL_ACCEPTANCE_OK';
